let departmentView=null,employeeView=null,projectTrail=null;
function ensureHierarchy(){
 for(const a of agents){a.level=3;if(a.parentId===undefined)a.parentId=managers.find(m=>m.dept===a.dept)?.id??null;const m=supervisor(a);if(!m)a.parentId=null;a.dept=m?.dept||'待分配';}
 for(const p of projects)for(const t of p.tasks){const a=agents.find(a=>a.id===t.agent);if(a)t.supervisorId=a.parentId;}
 for(const m of managers){m.duties??=({'策略部':'目标拆解、任务规划与执行协调','研究部':'资料搜集、行业洞察与机会分析','内容部':'文案创作、内容编辑与表达优化','数据部':'数据整理、指标分析与复盘'})[m.dept]||'';const children=agents.filter(a=>a.parentId===m.id),tasks=projects.flatMap(p=>p.tasks).filter(t=>children.some(a=>a.id===t.agent));m.status=`管理 ${children.length} 位员工 · ${tasks.filter(t=>t.status==='doing').length} 项进行中 · ${tasks.filter(t=>t.status==='error').length} 项异常`;}
}
function refresh(){updateDerived();if(view==='project')project(current);else if(view==='home')home(filter);else if(view==='commander')commanderPanel();else if(view==='manager')managers.some(m=>m.id===managerView)?managerPanel(managerView):departments();else if(view==='departments')departments();else if(view==='department')department(departmentView);else if(view==='employee')employeePanel(employeeView);else if(view==='settings')settings();else sync();}
function navigationPath(){
 let path=[['总指挥','home()']];
 if(['departments','department','employee'].includes(view)){path.push(['部门与团队','departments()']);const a=agents.find(a=>a.id===employeeView),m=managers.find(m=>m.id===(view==='employee'?a?.parentId:departmentView));if(view!=='departments'&&m)path.push([m.dept,`department(${m.id})`]);if(view==='employee'&&a)path.push([a.name,`employeePanel(${a.id})`]);}
 else if(view==='project'){path=projectTrail?[...projectTrail]:path;const p=projects.find(p=>p.id===current);if(p)path.push([p.name,`project(${p.id})`]);}
 else if(view==='settings')path.push(['Agent API 配置','settings()']);
 else if(['commander','manager'].includes(view)){path.push(['指挥团队','commanderPanel()']);if(view==='manager'){const m=managers.find(m=>m.id===managerView);if(m)path.push([m.name,`managerPanel(${m.id})`]);}}
 return path;
}
function renderBreadcrumbs(){const path=navigationPath();$('#crumb').innerHTML=path.map(([label,action],i)=>(i?'<span class="crumb-divider" aria-hidden="true">/</span>':'')+(i===path.length-1?`<span aria-current="page">${esc(label)}</span>`:`<button onclick="${action}">${esc(label)}</button>`)).join('');
}
function departmentActions(m){return `<div class="team-actions"><button class="secondary icon-button" title="编辑部门名称与职责" aria-label="编辑部门名称与职责" onclick="editDepartment(${m.id})">${uiIcon('edit')}</button><button class="secondary" onclick="manageMembers(${m.id})">管理成员</button><button class="secondary icon-button" title="删除部门" aria-label="删除部门" onclick="deleteDepartment(${m.id})">${uiIcon('trash')}</button></div>`;}
function employeeRows(list,mid=null){return list.map(a=>`<div class="worker-row"><div class="avatar ${esc(a.color||'')}">${esc(a.name.slice(0,1))}</div><div class="worker-info"><button class="employee-link" onclick="employeePanel(${a.id})">${esc(a.name)}</button><p>${esc(a.role)} · ${esc(a.dept)}</p><small>${esc(a.status)}</small></div><div class="team-actions"><button class="secondary icon-button" title="编辑员工" aria-label="编辑员工 ${esc(a.name)}" onclick="editEmployee(${a.id})">${uiIcon('edit')}</button><button class="secondary icon-button" title="对话" aria-label="与 ${esc(a.name)} 对话" onclick="chat(${a.id})">${uiIcon('chat')}</button>${mid!==null?`<button class="secondary" onclick="removeMember(${a.id},${mid})">移出部门</button>`:''}<button class="secondary icon-button" title="删除员工" aria-label="删除员工 ${esc(a.name)}" onclick="deleteEmployee(${a.id})">${uiIcon('trash')}</button></div></div>`).join('')||'<div class="empty">暂无员工，添加员工或从公司调入成员。</div>';}
function departments(){updateDerived();view='departments';current=null;$('#content').innerHTML=`<div class="heading"><div><h1>让专业的人，做专业的事。</h1><p>按部门组织你的 AI 员工，让分工更清晰。</p></div><div class="team-actions"><button class="secondary" onclick="editEmployee()">＋ 员工</button><button class="primary" onclick="editDepartment()">＋ 部门</button></div></div><div class="department-grid">${managers.map((m,i)=>`<section class="panel dept-card"><button class="department-link" onclick="department(${m.id})"><span class="picon">${['◇','◈','▤','▥'][i%4]}</span><h3>${esc(m.dept)} ↗</h3></button><p>${agents.filter(a=>a.parentId===m.id).length} 位员工 · ${esc(m.name)}<br>${esc(m.duties||'暂未设置部门职责')}</p>${departmentActions(m)}</section>`).join('')||'<div class="empty">暂无部门，添加部门以建立指挥团队。</div>'}</div><section class="panel"><div class="panel-head"><h2>公司员工 <span class="small muted">${agents.length} 位</span></h2><button class="secondary" onclick="editEmployee()">＋ 添加员工</button></div>${employeeRows(agents)}</section>`;sync();}
function department(id){const m=managers.find(m=>m.id===id||m.dept===id);if(!m)return departments();updateDerived();view='department';departmentView=m.id;current=null;const list=agents.filter(a=>a.parentId===m.id);$('#content').innerHTML=`<button class="back" onclick="departments()">← 所有部门</button><div class="heading"><div><h1>${esc(m.dept)}</h1><p>${esc(m.duties||'暂未设置部门职责')}</p></div>${departmentActions(m)}</div><section class="panel"><div class="panel-head"><h2>部门成员 · ${list.length}</h2><div class="team-actions"><button class="secondary" onclick="managerPanel(${m.id})">${esc(m.name)} ↗</button><button class="primary" onclick="editEmployee(null,${m.id})">＋ 员工</button></div></div>${employeeRows(list,m.id)}</section><h2 style="margin-bottom:16px">参与项目</h2><section class="panel">${rows(projects.filter(p=>p.tasks.some(t=>list.some(a=>a.id===t.agent))))}</section>`;sync();}
function employeePanel(id){const a=agents.find(a=>a.id===id);if(!a)return departments();updateDerived();view='employee';employeeView=id;current=null;$('#content').innerHTML=`<div class="heading"><div><h1>${esc(a.name)}</h1><p>${esc(a.dept)} · ${esc(a.role)}</p></div><div class="team-actions"><button class="secondary" onclick="editEmployee(${id})">编辑员工</button><button class="primary" onclick="chat(${id})">对话</button></div></div><section class="panel"><div class="panel-head"><h2>当前状态</h2></div><div class="dept-card">${esc(a.status)}</div></section><h2 style="margin-bottom:16px">参与项目</h2><section class="panel">${rows(projects.filter(p=>p.tasks.some(t=>t.agent===id)))}</section>`;sync();}
function editDepartment(id=null){const m=managers.find(m=>m.id===id);modal(m?'编辑部门':'添加部门','每个部门由一位二级性能指挥管理。',`<form onsubmit="event.preventDefault();saveDepartment(this,${id})"><label class="field">部门名称<input name="dept" required maxlength="30" value="${esc(m?.dept||'')}"></label><label class="field">部门职责<textarea name="duties" maxlength="500">${esc(m?.duties||'')}</textarea></label><label class="field">二级指挥名称<input name="name" required maxlength="30" value="${esc(m?.name||'')}" placeholder="例如：运营指挥"></label><div class="modal-footer"><button type="button" class="secondary" onclick="closeModal()">取消</button><button class="primary">保存</button></div></form>`);}
function saveDepartment(form,id){const d=new FormData(form),dept=String(d.get('dept')||'').trim(),name=String(d.get('name')||'').trim();if(!dept||!name)return toast('请填写部门和指挥名称');if(managers.some(m=>m.id!==id&&m.dept===dept))return toast('部门名称已存在');let m=managers.find(m=>m.id===id);if(!m){m={id:nextTeamId(true),level:2,parentId:0,role:'二级性能指挥',model:'manager-model',endpoint:'https://api.example.com/v1'};managers.push(m);}Object.assign(m,{dept,name,duties:String(d.get('duties')||'').trim()});logs.unshift([`保存部门「${dept}」的名称与职责`,'刚刚']);closeModal();department(m.id);toast('部门已保存');}
function nextTeamId(manager=false){let id=Date.now()*(manager?-1:1);while(findAgent(id))id+=manager?-1:1;return id;}
function releaseEmployee(a){for(const p of projects)for(const t of p.tasks.filter(t=>t.agent===a.id)){t.runToken=(t.runToken||0)+1;t.formerAgentName=a.name;t.agent=null;t.supervisorId=null;if(t.status==='doing'){t.status='todo';t.phase='paused';}t.readVersion=0;}a.parentId=null;a.dept='待分配';}
function changeMembership(a,mid){if(a.parentId===mid)return;releaseEmployee(a);const m=managers.find(m=>m.id===mid);a.parentId=m?.id??null;a.dept=m?.dept||'待分配';}
function manageMembers(id){const m=managers.find(m=>m.id===id);if(!m)return;modal('管理部门成员',`为「${esc(m.dept)}」增减公司员工。调动成员时，其任务停止并等待重新分派。`,`<form onsubmit="event.preventDefault();saveMembers(this,${id})"><div class="member-list">${agents.map(a=>`<label class="member-choice"><input type="checkbox" name="members" value="${a.id}" ${a.parentId===id?'checked':''}><span><b>${esc(a.name)}</b><small>${esc(a.role)} · ${esc(a.dept)}${a.parentId!==null&&a.parentId!==id?'（选中后调入）':''}</small></span></label>`).join('')||'<div class="empty">请先添加公司员工。</div>'}</div><div class="modal-footer"><button class="secondary" type="button" onclick="closeModal()">取消</button><button class="primary">保存成员</button></div></form>`);}
function saveMembers(form,id){if(!managers.some(m=>m.id===id))return;const selected=new Set(new FormData(form).getAll('members').map(Number));for(const a of agents)if(selected.has(a.id))changeMembership(a,id);else if(a.parentId===id)changeMembership(a,null);logs.unshift([`更新「${findAgent(id).dept}」部门成员`,'刚刚']);closeModal();refresh();toast('部门成员已更新');}
function removeMember(id,mid){const a=agents.find(a=>a.id===id);if(!a||a.parentId!==mid)return;modal('移出部门',`「${esc(a.name)}」将保留在公司员工中，当前执行停止，任务等待重新分派。`,`<div class="modal-footer"><button class="secondary" onclick="closeModal()">取消</button><button class="primary" onclick="confirmRemoveMember(${id},${mid})">确认移出</button></div>`);}
function confirmRemoveMember(id,mid){const a=agents.find(a=>a.id===id);if(!a||a.parentId!==mid)return;changeMembership(a,null);logs.unshift([`${a.name} 已移出部门，等待调配`,'刚刚']);closeModal();refresh();toast('员工已移出部门');}
function deleteDepartment(id){const m=managers.find(m=>m.id===id);if(!m)return;modal('删除部门',`删除「${esc(m.dept)}」及其二级指挥。部门员工保留为待分配，相关执行停止；项目和历史备份保留。`,`<div class="modal-footer"><button class="secondary" onclick="closeModal()">取消</button><button class="danger" onclick="confirmDeleteDepartment(${id})">确认删除部门</button></div>`);}
function confirmDeleteDepartment(id){const m=managers.find(m=>m.id===id);if(!m)return;for(const a of agents.filter(a=>a.parentId===id))releaseEmployee(a);for(const p of projects)for(const t of p.tasks)if(t.supervisorId===id)t.supervisorId=null;managers=managers.filter(m=>m.id!==id);delete chats[id];logs.unshift([`删除部门「${m.dept}」，员工保留待分配`,'刚刚']);closeModal();departments();toast('部门已删除');}
function editEmployee(id=null,mid=null){const a=agents.find(a=>a.id===id);modal(a?'编辑员工':'添加公司员工','员工加入部门后，由该部门的二级指挥分派任务。',`<form onsubmit="event.preventDefault();saveEmployee(this,${id})"><label class="field">员工名称<input name="name" required maxlength="30" value="${esc(a?.name||'')}"></label><label class="field">员工职责<input name="role" required maxlength="100" value="${esc(a?.role||'')}"></label><label class="field">所属部门<select name="parentId"><option value="">待分配</option>${managers.map(m=>`<option value="${m.id}" ${(a?a.parentId:mid)===m.id?'selected':''}>${esc(m.dept)} · ${esc(m.name)}</option>`).join('')}</select></label><div class="modal-footer"><button class="secondary" type="button" onclick="closeModal()">取消</button><button class="primary">保存员工</button></div></form>`);}
function saveEmployee(form,id){const d=new FormData(form),name=String(d.get('name')||'').trim(),role=String(d.get('role')||'').trim();if(!name||!role)return toast('请填写员工名称和职责');let a=agents.find(a=>a.id===id);if(!a){a={id:nextTeamId(),parentId:null,level:3,color:'mint',model:'custom-model',endpoint:'https://api.example.com/v1'};agents.push(a);}changeMembership(a,Number(d.get('parentId'))||null);Object.assign(a,{name,role});logs.unshift([`保存员工「${name}」的信息`,'刚刚']);closeModal();refresh();toast('员工已保存');}
function deleteEmployee(id){const a=agents.find(a=>a.id===id);if(!a)return;modal('删除员工',`删除「${esc(a.name)}」。其执行立即停止，任务保留待重新分派；已完成任务和历史备份保留。`,`<div class="modal-footer"><button class="secondary" onclick="closeModal()">取消</button><button class="danger" onclick="confirmDeleteEmployee(${id})">确认删除员工</button></div>`);}
function confirmDeleteEmployee(id){const a=agents.find(a=>a.id===id);if(!a)return;releaseEmployee(a);agents=agents.filter(a=>a.id!==id);delete chats[id];logs.unshift([`删除员工「${a.name}」，保留项目与历史记录`,'刚刚']);closeModal();refresh();toast('员工已删除');}
